using System;using System.Data;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Windows.Forms;
class DeliveryFeeRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Assembly app;static int checks;
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static void Put(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}static decimal Fee(object o){return Convert.ToDecimal(Get(Field(o,"tbDeliveryFee"),"Value"));}
 static void Run(string name,DataTable rows){var type=app.GetType(name);var pad=(Control)FormatterServices.GetUninitializedObject(type);(type.BaseType==typeof(Form)?typeof(Form):typeof(UserControl)).GetConstructor(Type.EmptyTypes).Invoke(pad,new object[0]);using(pad){Call(pad,"InitializeComponent");Call(pad,"InitOrderItemTable");Call(pad,"InitOrderEditor");Call(pad,"InitPreviewEvent");var combo=Field(pad,"cbDeliveryType");Set(Field(pad,"tbDeliveryFee"),"Value",8000m);Put(pad,"m_isInitializing",true);Call(pad,"LoadTextCombo",combo,rows.Select());Check(Fee(pad)==8000m,"Loading saved values does not replace fee");Put(pad,"m_isInitializing",false);Call(pad,"ApplySelectedDeliveryFee");Check(Fee(pad)==3500m,"Default shipping fee from ItemValue");Set(combo,"SelectedIndex",1);Check(Fee(pad)==0m,"Missing ItemValue clears fee to zero");Set(combo,"SelectedIndex",2);Check(Fee(pad)==5000m,"Formatted amount applied on selection");Set(combo,"SelectedIndex",3);Check(Fee(pad)==0m,"Invalid fee clears stale amount");Set(combo,"SelectedIndex",4);Check(Fee(pad)==0m,"Negative fee not applied");Put(pad,"m_isInitializing",true);Set(combo,"SelectedIndex",0);Set(Field(pad,"tbDeliveryFee"),"Value",9100m);Put(pad,"m_isInitializing",false);Check(Fee(pad)==9100m,"Stored fee preserved when loading completed");Set(combo,"Enabled",false);Set(combo,"SelectedIndex",2);Check(Fee(pad)==9100m,"Linked original fee is preserved");Set(combo,"Enabled",true);Call(pad,"ApplySelectedDeliveryFee");Check(Fee(pad)==5000m,"Unlocked selection applies configured fee");Call(pad,"ResetNewOrder");Check(Fee(pad)==3500m,"New order default shipping fee refreshed");var save=Call(pad,"CreateOrderSaveData");Check((decimal)Get(save,"DeliveryFee")==3500m,"Fee included in save model");}}
 [STAThread]static int Main(string[]args){try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));var t=new DataTable();t.Columns.Add("ItemName");t.Columns.Add("ItemValue");t.Rows.Add("선불택배","3500");t.Rows.Add("창고",DBNull.Value);t.Rows.Add("방문수령","5,000");t.Rows.Add("잘못된값","invalid");t.Rows.Add("음수","-1");Run("PineTree.UserControls.UcOrderDesignPad",t);Run("PineTree.Dialogs.DialogOrderDesignPad",t);if(args.Length>1){var actual=(DataTable)app.GetType("PineTree.Classes.CommonCodeRepository").GetMethod("GetOrderEntryItems").Invoke(null,null);Check(actual.Columns.Contains("ItemValue"),"Live query exposes configured ItemValue");Console.WriteLine("PASS: live CommonCode query");}Console.WriteLine("PASS: "+checks+" shipping-fee checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
